export const getNodeOutboundsLatencyUrl = (nodeId: number,
    params?: NodeOutboundsLatencyParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/node/${nodeId}/outbounds_latency?${stringifiedParams}` : `/api/node/${nodeId}/outbounds_latency`
}

